const D = { energy: .6, scale: 1, speed: 1, density: .5, depth: .5, flow: .6, grain: .4, hue: 30, x: .5, y: .5, style: 'bmode', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------------------------------------------------------------------------
// Ultrasound sector -- a curvilinear B-mode fan from a transducer at the apex.
// Rayleigh speckle scrolls through the tissue, specular interfaces undulate as
// bright arcs, a pulsing organ wall throbs on the cardiac cycle, and a colour
// Doppler box paints flow red-toward / blue-away inside a vessel. Near-field
// bright, far-field softened by time-gain-compensated attenuation, the whole
// image shimmering the way live scanning does. B-mode grey, colour Doppler,
// amber power Doppler, or a schematic of iso-echo contours.
// ---------------------------------------------------------------------------
const sd = P.seed | 0;
function hh(ix, iy) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd + 3, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
function sstep(t) { return t * t * (3 - 2 * t); }
function vnoise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y), xf = sstep(x - xi), yf = sstep(y - yi);
  const a = hh(xi, yi), b = hh(xi + 1, yi), c = hh(xi, yi + 1), d = hh(xi + 1, yi + 1);
  return (a + (b - a) * xf) * (1 - yf) + (c + (d - c) * xf) * yf;
}
function fbm(x, y) { return vnoise(x, y) * 0.6 + vnoise(x * 2.1 + 5.1, y * 2.1 - 3.3) * 0.27 + vnoise(x * 4.3 - 2.2, y * 4.3 + 1.1) * 0.13; }

const BW = Math.max(360, Math.min(640, Math.round(width / 2.6)));
const BH = Math.max(120, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }

const ax = BW * 0.5, ay = BH * 0.02;
const theta = 0.66;                              // sector half-angle
const r0 = BH * 0.05, r1 = BH * 0.99;
const scroll = K.t * (0.15 + P.speed * 0.5);     // tissue drift down the beam
const drift = 0.5 * Math.sin(K.t * 0.29) + 0.32 * Math.sin(K.t * 0.61 + 1.4);
const heart = 0.5 + 0.5 * Math.sin(K.t * 1.55 + 0.5) + A.bass * 0.4;   // cardiac cycle
const spf = 3 + P.density * 6;                   // speckle fineness
const gain = 0.7 + P.energy * 0.8 + A.rms * 0.2;
const dgc = 1.2 + P.depth * 1.8;                 // attenuation depth
const style = P.style, gr = P.grain;
const dopH = P.hue;
const wallR = 0.42 + 0.05 * heart;               // pulsing wall radius (fraction of far)

const g = S.g; g.loadPixels(); const px = g.pixels;
for (let j = 0; j < BH; j++) {
  for (let i = 0; i < BW; i++) {
    const dx = i - ax, dy = j - ay;
    const r = Math.sqrt(dx * dx + dy * dy);
    const ang = Math.atan2(dx, dy);
    let R = 0.05, Gc = 0.06, Bc = 0.075;         // console dark-grey outside
    if (Math.abs(ang) < theta && r > r0 && r < r1) {
      const dd = (r - r0) / (r1 - r0);            // 0 near .. 1 far
      const an = ang / theta;                     // -1..1 across sector
      // Rayleigh speckle following beam lines
      const spk = fbm(an * spf * 4 + drift * 0.3, dd * spf * 9 + scroll);
      let echo = 0.28 + spk * 0.6;
      // specular tissue interfaces (undulating bright arcs)
      const iface = Math.sin(dd * 22 + Math.sin(an * 3 + K.t * 0.4) * 1.2 - K.t * 0.3);
      echo += Math.max(0, iface - 0.6) * 1.4;
      // pulsing organ wall + its acoustic shadow behind
      const wd = Math.abs(dd - wallR) - 0.012 * (1 - Math.abs(an));
      if (wd < 0.02) echo += (0.02 - Math.abs(wd)) * 22 * (0.6 + 0.4 * Math.cos(an * 2));
      if (dd > wallR + 0.02 && Math.abs(an) < 0.5) echo *= 0.55;   // shadow
      // time-gain-compensated attenuation (near bright, far softened)
      echo *= (1.15 - dd * 0.45) * Math.exp(-dd * dd * dgc * 0.4);
      echo = Math.max(0, echo * gain);
      // beam-edge darkening
      const edge = 1 - Math.pow(Math.abs(an), 6);
      echo *= 0.35 + 0.65 * edge;
      let v = Math.min(1, echo);

      // colour Doppler / power overlay inside a vessel ROI
      let flow = 0;
      if (style === 'doppler' || style === 'power') {
        const vx = an - 0.15, vy = dd - 0.55;
        const vessel = Math.abs(vx * 0.85 + vy * 0.5);         // diagonal tube
        const inbox = dd > 0.28 && dd < 0.82 && Math.abs(an) < 0.6;
        if (inbox && vessel < 0.09) {
          const prof = (1 - vessel / 0.09);
          const puls = 0.35 + 0.65 * Math.max(0, Math.sin(K.t * 1.55 + 0.5 - dd * 2));
          flow = prof * (0.4 + 0.9 * P.flow) * puls;
        }
      }
      if (style === 'doppler') {
        const towards = 0.5 + 0.5 * Math.sin(K.t * 1.55 - 0.6);   // direction alternates slowly (never strobe)
        R = v * 0.7 + flow * (towards) * 1.2;
        Gc = v * 0.72 + flow * 0.15;
        Bc = v * 0.74 + flow * (1 - towards) * 1.3;
      } else if (style === 'power') {
        const c = flow * (0.6 + P.energy);
        R = v * 0.72 + c * 1.15; Gc = v * 0.72 + c * (0.35 + dopH / 720); Bc = v * 0.7 + c * 0.05;
      } else if (style === 'schematic') {
        const iso = Math.abs((v * 8) % 1 - 0.5);
        const line = iso < 0.08 ? 1 : 0;
        R = 0.05 + line * 0.25 + v * 0.05; Gc = 0.09 + line * 0.7 + v * 0.08; Bc = 0.14 + line * 0.9 + v * 0.1;
      } else {
        R = v * 0.98; Gc = v; Bc = v * 1.02;      // bmode neutral grey
      }
      // speckle grain
      const nz = (fbm(i * 0.7, j * 0.7 + scroll * 2) - 0.5) * 0.12 * gr;
      R += nz; Gc += nz; Bc += nz;
    }
    const o = 4 * (j * BW + i);
    px[o] = Math.max(0, Math.min(255, R * 255));
    px[o + 1] = Math.max(0, Math.min(255, Gc * 255));
    px[o + 2] = Math.max(0, Math.min(255, Bc * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

const mag = Math.max(1, P.scale);
const sw = BW / mag, sh = BH / mag;
const sx = (BW - sw) * Math.min(1, Math.max(0, P.x)), sy = (BH - sh) * Math.min(1, Math.max(0, P.y));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height, sx, sy, sw, sh);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
